import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, doPartsIntersect } from '../../geometry';

interface PlacedItemCache {
    item: PackerItem;
    result: PlacedResult;
    // Кэшируем BBox в абсолютных координатах листа для быстрой проверки AABB
    bbox: { minX: number; minY: number; maxX: number; maxY: number };
}

export class ComplexPacker implements INestingPacker {
    private placedCache: PlacedItemCache[] = [];

    // Spatial Grid: Ключ ячейки -> Индексы деталей в this.placedCache
    private grid: Map<string, number[]> = new Map();
    private readonly cellSize = 100; // Размер ячейки сетки (мм)

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {}

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        const step = 5; // Шаг поиска

        // 1. Оптимизация: Сортируем и кэшируем габариты для всех ротаций заранее
        // Чтобы не считать sin/cos внутри цикла координат
        const rotationCandidates = [...item.allowedRotations];
        if (item.preferredRotation !== undefined && !rotationCandidates.includes(item.preferredRotation)) {
            rotationCandidates.unshift(item.preferredRotation);
        }

        const rotationCache = rotationCandidates.map(rot => ({
            rot,
            extents: getRotatedExtents(partDef, rot, this.tools)
        }));

        // Перебор позиций
        for (let x = 0; x <= this.sheetW - step; x += step) {
            // Даем UI "подышать" каждые 100 шагов по X, чтобы не зависал интерфейс
            if (x % 100 === 0) await new Promise(resolve => setTimeout(resolve, 0));

            for (const { rot, extents } of rotationCache) {
                if (x + extents.width > this.sheetW) continue;

                for (let y = 0; y <= this.sheetH - extents.height; y += step) {
                    const candidateOrigin: Point = { x: x + extents.ox, y: y + extents.oy };

                    // Абсолютный BBox кандидата (с учетом отступов для проверки коллизий)
                    // Добавляем spacing к BBox кандидата, чтобы гарантировать зазор
                    const candMinX = x; 
                    const candMinY = y;
                    const candMaxX = x + extents.width;
                    const candMaxY = y + extents.height;

                    // 2. Оптимизация: Получаем только соседей из сетки
                    const potentialCollisions = this.getGridNeighbors(candMinX, candMinY, candMaxX, candMaxY);

                    let collision = false;

                    for (const placedIdx of potentialCollisions) {
                        const placed = this.placedCache[placedIdx];

                        // 3. Оптимизация: AABB Pruning (Быстрая проверка прямоугольников)
                        // Проверяем пересечение с учетом Spacing
                        const spacing = Math.max(this.spacingX, this.spacingY);

                        // Check overlap including spacing
                        if (candMaxX + spacing <= placed.bbox.minX || 
                            candMinX - spacing >= placed.bbox.maxX || 
                            candMaxY + spacing <= placed.bbox.minY || 
                            candMinY - spacing >= placed.bbox.maxY) {
                            continue; // Прямоугольники не пересекаются
                        }

                        const pPartDef = this.parts.find(p => p.id === placed.item.partId);
                        if (!pPartDef) continue;

                        const pOrigin: Point = { 
                            x: placed.result.x + placed.result.ox, 
                            y: placed.result.y + placed.result.oy 
                        };

                        // 4. Дорогая геометрическая проверка (только если AABB пересеклись)
                        if (doPartsIntersect(
                            partDef, candidateOrigin, rot,
                            pPartDef, pOrigin, placed.result.rotation,
                            spacing
                        )) {
                            collision = true;
                            break;
                        }
                    }

                    if (!collision) {
                        return { x, y, rotation: rot, ox: extents.ox, oy: extents.oy, width: extents.width, height: extents.height };
                    }
                }
            }
        }
        return null;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        // Расчет абсолютного BBox для кэша
        const minX = result.x;
        const minY = result.y;
        const maxX = result.x + result.width;
        const maxY = result.y + result.height;

        const cacheEntry: PlacedItemCache = {
            item,
            result,
            bbox: { minX, minY, maxX, maxY }
        };

        const index = this.placedCache.length;
        this.placedCache.push(cacheEntry);

        // Добавление в пространственную сетку
        this.addToGrid(index, minX, minY, maxX, maxY);
    }

    getPlacedItems() { 
        return this.placedCache.map(c => ({ item: c.item, result: c.result })); 
    }

    // --- Spatial Hashing Helpers ---

    private getGridKey(cx: number, cy: number): string {
        return `${cx}_${cy}`;
    }

    private addToGrid(itemIdx: number, minX: number, minY: number, maxX: number, maxY: number) {
        const startX = Math.floor(minX / this.cellSize);
        const endX = Math.floor(maxX / this.cellSize);
        const startY = Math.floor(minY / this.cellSize);
        const endY = Math.floor(maxY / this.cellSize);

        for (let x = startX; x <= endX; x++) {
            for (let y = startY; y <= endY; y++) {
                const key = this.getGridKey(x, y);
                if (!this.grid.has(key)) {
                    this.grid.set(key, []);
                }
                this.grid.get(key)!.push(itemIdx);
            }
        }
    }

    private getGridNeighbors(minX: number, minY: number, maxX: number, maxY: number): number[] {
        const startX = Math.floor(minX / this.cellSize);
        const endX = Math.floor(maxX / this.cellSize);
        const startY = Math.floor(minY / this.cellSize);
        const endY = Math.floor(maxY / this.cellSize);

        const indices = new Set<number>();

        for (let x = startX; x <= endX; x++) {
            for (let y = startY; y <= endY; y++) {
                const key = this.getGridKey(x, y);
                const cellItems = this.grid.get(key);
                if (cellItems) {
                    for (const idx of cellItems) {
                        indices.add(idx);
                    }
                }
            }
        }
        return Array.from(indices);
    }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, isPointInsideContour, doPartsIntersect } from '../../geometry';

interface RasterMask {
    width: number;
    height: number;
    data: Uint8Array; // 1 = Part Material, 0 = Empty
    offsetX: number;  // Смещение внутри маски до начала координат (0,0) детали
    offsetY: number;
}

export class ComplexPacker implements INestingPacker {
    // Глобальная сетка листа: 1D массив, эмулирующий 2D (index = y * width + x)
    // 0 = Свободно, 1 = Занято
    private grid: Uint8Array;
    private readonly gridW: number;
    private readonly gridH: number;
    private readonly resolution: number = 1; // 1 пиксель = 1 мм

    // Кэш растеризованных масок для (PartId + Rotation)
    // Ключ: `${partId}_${rotation}`
    private maskCache: Map<string, RasterMask> = new Map();

    private placedItems: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.gridW = Math.ceil(sheetW / this.resolution);
        this.gridH = Math.ceil(sheetH / this.resolution);
        // Инициализируем пустую сетку
        this.grid = new Uint8Array(this.gridW * this.gridH);
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        // Эвристика: пробуем вращения
        // Сначала предпочтительное, потом 0, потом остальные
        const rotations = [...item.allowedRotations];
        if (item.preferredRotation !== undefined && !rotations.includes(item.preferredRotation)) {
            rotations.unshift(item.preferredRotation);
        }

        // Шаг поиска по сетке (можно увеличить для скорости, но упадет плотность)
        const step = 2; 

        for (const rot of rotations) {
            // 1. Получаем или генерируем маску для этого поворота
            const mask = this.getOrGenerateMask(partDef, rot);

            // Если деталь больше листа — пропускаем
            if (mask.width > this.gridW || mask.height > this.gridH) continue;

            // 2. Скользим маской по сетке листа
            // limitY и limitX - пределы, чтобы маска не вылезла за край
            const limitY = this.gridH - mask.height;
            const limitX = this.gridW - mask.width;

            for (let y = 0; y <= limitY; y += step) {
                // Оптимизация: даем UI дышать на больших листах
                if (y % 100 === 0) await new Promise(r => setTimeout(r, 0));

                for (let x = 0; x <= limitX; x += step) {
                    if (!this.checkCollision(x, y, mask)) {
                        // Нашли место!
                        // Возвращаем координаты в миллиметрах
                        // Учитываем offsetX/Y маски, чтобы вернуть координату (0,0) самой детали
                        // mask.offsetX/Y уже включены в систему координат маски
                        return {
                            x: x * this.resolution,
                            y: y * this.resolution,
                            rotation: rot,
                            width: mask.width * this.resolution,
                            height: mask.height * this.resolution,
                            ox: mask.offsetX,
                            oy: mask.offsetY
                        };
                    }
                }
            }
        }

        return null;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return;

        // Получаем ту же маску
        const mask = this.getOrGenerateMask(partDef, result.rotation);

        // Координаты сетки
        const gridX = Math.round(result.x / this.resolution);
        const gridY = Math.round(result.y / this.resolution);

        // "Впечатываем" маску в сетку (пишем 1 там, где деталь)
        this.writeMaskToGrid(gridX, gridY, mask);

        this.placedItems.push({ item, result });
    }

    getPlacedItems() {
        return this.placedItems;
    }

    // --- Private Methods ---

    /**
     * Проверяет наложение маски детали на текущую сетку листа.
     * Возвращает true, если есть коллизия (место занято).
     */
    private checkCollision(sx: number, sy: number, mask: RasterMask): boolean {
        // Проходим по всем пикселям маски
        // Оптимизация: используем одномерные индексы
        for (let my = 0; my < mask.height; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                // Если в маске есть "материал" (1)
                if (mask.data[maskRowOffset + mx] === 1) {
                    // Проверяем соответствующую ячейку листа
                    if (this.grid[sheetRowOffset + mx] === 1) {
                        return true; // Столкновение
                    }
                }
            }
        }
        return false;
    }

    /**
     * Записывает деталь в сетку листа.
     */
    private writeMaskToGrid(sx: number, sy: number, mask: RasterMask) {
        for (let my = 0; my < mask.height; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    this.grid[sheetRowOffset + mx] = 1;
                }
            }
        }
    }

    /**
     * Создает или достает из кэша растровую маску детали.
     * Маска включает в себя Spacing (отступ безопасности).
     */
    private getOrGenerateMask(part: Part, rotation: number): RasterMask {
        const key = `${part.id}_${rotation}`;
        if (this.maskCache.has(key)) {
            return this.maskCache.get(key)!;
        }

        // 1. Считаем физические габариты при повороте
        const extents = getRotatedExtents(part, rotation, this.tools);

        // 2. Добавляем Spacing к размеру маски
        // Мы растеризуем деталь "жирнее" на величину зазора, чтобы обеспечить отступ
        // Spacing берется максимальный из X и Y для безопасности
        const spacing = Math.ceil(Math.max(this.spacingX, this.spacingY) / this.resolution);

        const rawW = Math.ceil(extents.width / this.resolution);
        const rawH = Math.ceil(extents.height / this.resolution);

        const maskW = rawW + spacing; // Добавляем spacing только справа/снизу? 
        // Нет, лучше симметрично, но для простоты упаковки мы обычно добавляем отступ "справа и снизу" 
        // или считаем, что маска представляет "зону отчуждения".
        const maskH = rawH + spacing;

        const data = new Uint8Array(maskW * maskH);

        // 3. Растеризация (Сканируем каждый пиксель внутри BBox)
        // Это делается 1 раз на деталь+поворот, так что тут можно потратить время процессора.

        // Векторные параметры для поворота
        const rad = -rotation * Math.PI / 180; // Обратный поворот для проверки точки
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);

        // ox, oy - смещение внутри BBox до точки (0,0) оригинальной детали
        // extents.ox/oy положительны и указывают на сдвиг

        // Проходим по пикселям маски
        for (let y = 0; y < rawH; y++) {
            for (let x = 0; x < rawW; x++) {
                // Координата точки относительно левого верхнего угла BBox (в мм)
                // Сдвигаем на 0.5, чтобы проверять центр пикселя
                const bboxX = x * this.resolution;
                const bboxY = y * this.resolution;

                // Переводим в локальные координаты детали (до поворота)
                // Сначала вычитаем смещение BBox, чтобы получить координаты относительно (0,0) повернутой детали
                const rotX = bboxX + extents.ox;
                const rotY = bboxY + extents.oy;

                // Теперь поворачиваем точку обратно, чтобы проверить её в исходной геометрии (которая не повернута)
                const localX = rotX * cos - rotY * sin;
                const localY = rotX * sin + rotY * cos;

                // Проверяем, внутри ли контура
                if (isPointInsideContour({ x: localX, y: localY }, part.geometry)) {
                    // Рисуем деталь
                    data[y * maskW + x] = 1;

                    // Рисуем Spacing (расширяем точку вправо и вниз, и влево-вверх для простоты "жирной" кисти?)
                    // Проще: если точка внутри детали, то мы помечаем её как занятую.
                    // А Spacing обеспечивается тем, что мы проверяем "пустоту" в checkCollision.
                    // НО! Если мы хотим гарантированный зазор, нам нужно "раздуть" маску.

                    // Простой алгоритм раздутия (Dilation) на величину spacing
                    if (spacing > 0) {
                        for (let dy = 0; dy <= spacing; dy++) {
                            for (let dx = 0; dx <= spacing; dx++) {
                                const targetIdx = (y + dy) * maskW + (x + dx);
                                if (targetIdx < data.length) {
                                    data[targetIdx] = 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        const mask: RasterMask = {
            width: maskW,
            height: maskH,
            data: data,
            offsetX: extents.ox,
            offsetY: extents.oy
        };

        this.maskCache.set(key, mask);
        return mask;
    }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, isPointInsideContour } from '../../geometry';

interface RasterMask {
    width: number;
    height: number;
    data: Uint8Array; // 1 = Part Material, 0 = Empty
    offsetX: number;  // Смещение внутри маски до начала координат (0,0) детали
    offsetY: number;
}

export class ComplexPacker implements INestingPacker {
    // Глобальная сетка листа: 1D массив, эмулирующий 2D (index = y * width + x)
    // 0 = Свободно, 1 = Занято
    private grid: Uint8Array;
    private readonly gridW: number;
    private readonly gridH: number;
    private readonly resolution: number = 1; // 1 пиксель = 1 мм

    // Оптимизация: отслеживаем максимальную заполненную высоту, чтобы не сканировать весь лист
    private maxFilledY: number = 0; 

    // Кэш растеризованных масок для (PartId + Rotation)
    // Ключ: `${partId}_${rotation}`
    private maskCache: Map<string, RasterMask> = new Map();

    private placedItems: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.gridW = Math.ceil(sheetW / this.resolution);
        this.gridH = Math.ceil(sheetH / this.resolution);
        this.grid = new Uint8Array(this.gridW * this.gridH);
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        // Собираем уникальные ротации для проверки
        const rotations = Array.from(new Set([
            ...(item.preferredRotation !== undefined ? [item.preferredRotation] : []),
            ...item.allowedRotations
        ]));

        const step = 2; // Шаг сканирования (мм)

        let bestResult: PlacedResult | null = null;

        // Стратегия BEST FIT:
        // Проверяем ВСЕ ротации и ищем ту, которая даст позицию с минимальным Y (и затем X).
        // Это позволяет детали "проваливаться" в дырки, которые доступны только при определенном повороте.

        for (const rot of rotations) {
            const mask = this.getOrGenerateMask(partDef, rot);

            // Если деталь больше листа — пропускаем этот поворот
            if (mask.width > this.gridW || mask.height > this.gridH) continue;

            const limitX = this.gridW - mask.width;

            // Оптимизация: ищем только до текущей высоты заполнения + высота детали.
            // Нет смысла искать в пустоте на 2 метра дальше.
            // Добавляем небольшой буфер (50мм) на всякий случай.
            const searchLimitY = Math.min(this.gridH - mask.height, this.maxFilledY + mask.height + 50);

            // Сканируем лист для ЭТОЙ ротации
            let foundPosForRot: { x: number, y: number } | null = null;

            yLoop: for (let y = 0; y <= searchLimitY; y += step) {
                // UI responsiveness break
                if (y % 200 === 0) await new Promise(r => setTimeout(r, 0));

                for (let x = 0; x <= limitX; x += step) {
                    if (!this.checkCollision(x, y, mask)) {
                        foundPosForRot = { x, y };
                        break yLoop; // Нашли лучшее место для ЭТОЙ ротации (т.к. сканируем Y->X)
                    }
                }
            }

            if (foundPosForRot) {
                const candidate: PlacedResult = {
                    x: foundPosForRot.x * this.resolution,
                    y: foundPosForRot.y * this.resolution,
                    rotation: rot,
                    width: mask.width * this.resolution,
                    height: mask.height * this.resolution,
                    ox: mask.offsetX,
                    oy: mask.offsetY
                };

                // Сравниваем с текущим лучшим результатом
                // Приоритет: Чем меньше Y, тем лучше. При равном Y, чем меньше X.
                if (!bestResult) {
                    bestResult = candidate;
                } else {
                    if (candidate.y < bestResult.y) {
                        bestResult = candidate;
                    } else if (candidate.y === bestResult.y && candidate.x < bestResult.x) {
                        bestResult = candidate;
                    }
                }
            }
        }

        return bestResult;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return;

        const mask = this.getOrGenerateMask(partDef, result.rotation);

        const gridX = Math.round(result.x / this.resolution);
        const gridY = Math.round(result.y / this.resolution);

        this.writeMaskToGrid(gridX, gridY, mask);

        // Обновляем границу заполнения
        const itemBottomY = gridY + mask.height;
        if (itemBottomY > this.maxFilledY) {
            this.maxFilledY = itemBottomY;
        }

        this.placedItems.push({ item, result });
    }

    getPlacedItems() {
        return this.placedItems;
    }

    // --- Private Methods ---

    private checkCollision(sx: number, sy: number, mask: RasterMask): boolean {
        // Проверка границ массива (fail-safe)
        if (sx + mask.width > this.gridW || sy + mask.height > this.gridH) return true;

        // Быстрая проверка центра (эвристика: часто коллизия бывает в центре детали)
        const centerY = Math.floor(mask.height / 2);
        const centerX = Math.floor(mask.width / 2);
        const sheetIdxCenter = (sy + centerY) * this.gridW + (sx + centerX);
        const maskIdxCenter = centerY * mask.width + centerX;

        if (mask.data[maskIdxCenter] === 1 && this.grid[sheetIdxCenter] === 1) return true;

        // Полная проверка
        for (let my = 0; my < mask.height; my++) {
            // Оптимизация: вычисляем индексы строк заранее
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    if (this.grid[sheetRowOffset + mx] === 1) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private writeMaskToGrid(sx: number, sy: number, mask: RasterMask) {
        for (let my = 0; my < mask.height; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    this.grid[sheetRowOffset + mx] = 1;
                }
            }
        }
    }

    private getOrGenerateMask(part: Part, rotation: number): RasterMask {
        const key = `${part.id}_${rotation}`;
        if (this.maskCache.has(key)) {
            return this.maskCache.get(key)!;
        }

        const extents = getRotatedExtents(part, rotation, this.tools);

        // Учитываем spacing в маске
        const spacing = Math.ceil(Math.max(this.spacingX, this.spacingY) / this.resolution);

        const rawW = Math.ceil(extents.width / this.resolution);
        const rawH = Math.ceil(extents.height / this.resolution);

        // Маска чуть больше реальной детали на величину зазора
        const maskW = rawW + spacing; 
        const maskH = rawH + spacing;

        const data = new Uint8Array(maskW * maskH);

        const rad = -rotation * Math.PI / 180;
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);

        for (let y = 0; y < rawH; y++) {
            for (let x = 0; x < rawW; x++) {
                const bboxX = x * this.resolution;
                const bboxY = y * this.resolution;

                const rotX = bboxX + extents.ox;
                const rotY = bboxY + extents.oy;

                const localX = rotX * cos - rotY * sin;
                const localY = rotX * sin + rotY * cos;

                if (isPointInsideContour({ x: localX, y: localY }, part.geometry)) {
                    // Заполняем саму точку
                    const idx = y * maskW + x;
                    data[idx] = 1;

                    // "Раздуваем" точку на spacing (вправо и вниз)
                    // Это создает зону безопасности вокруг детали
                    if (spacing > 0) {
                        // Рисуем линию вправо
                        for(let s=1; s<=spacing; s++) {
                            if (x + s < maskW) data[y * maskW + (x + s)] = 1;
                        }
                        // Рисуем линию вниз (и прямоугольник заполнения)
                        for(let sy=1; sy<=spacing; sy++) {
                            if (y + sy < maskH) {
                                const rowOff = (y + sy) * maskW;
                                for(let sx=0; sx<=spacing; sx++) {
                                    if (x + sx < maskW) data[rowOff + (x + sx)] = 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        const mask: RasterMask = {
            width: maskW,
            height: maskH,
            data: data,
            offsetX: extents.ox,
            offsetY: extents.oy
        };

        this.maskCache.set(key, mask);
        return mask;
    }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, isPointInsideContour } from '../../geometry';

interface RasterMask {
    width: number;
    height: number;
    data: Uint8Array; // 1 = Part Material, 0 = Empty
    offsetX: number;  // Смещение внутри маски до начала координат (0,0) детали
    offsetY: number;
}

export class ComplexPacker implements INestingPacker {
    // Глобальная сетка листа: 1D массив, эмулирующий 2D (index = y * width + x)
    // 0 = Свободно, 1 = Занято
    private grid: Uint8Array;
    private readonly gridW: number;
    private readonly gridH: number;
    private readonly resolution: number = 1; // 1 пиксель = 1 мм

    // Оптимизация: отслеживаем максимальную заполненную высоту, чтобы не сканировать весь лист
    private maxFilledY: number = 0; 

    // Кэш растеризованных масок для (PartId + Rotation)
    // Ключ: `${partId}_${rotation}`
    private maskCache: Map<string, RasterMask> = new Map();

    private placedItems: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.gridW = Math.ceil(sheetW / this.resolution);
        this.gridH = Math.ceil(sheetH / this.resolution);
        this.grid = new Uint8Array(this.gridW * this.gridH);
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        // Собираем уникальные ротации для проверки
        const rotations = Array.from(new Set([
            ...(item.preferredRotation !== undefined ? [item.preferredRotation] : []),
            ...item.allowedRotations
        ]));

        const step = 2; // Шаг сканирования (мм)

        let bestResult: PlacedResult | null = null;

        // Стратегия BEST FIT:
        // Проверяем ВСЕ ротации и ищем ту, которая даст позицию с минимальным Y (и затем X).
        // Это позволяет детали "проваливаться" в дырки, которые доступны только при определенном повороте.

        for (const rot of rotations) {
            const mask = this.getOrGenerateMask(partDef, rot);

            // Если деталь больше листа — пропускаем этот поворот
            if (mask.width > this.gridW || mask.height > this.gridH) continue;

            const limitX = this.gridW - mask.width;

            // Оптимизация: ищем только до текущей высоты заполнения + высота детали.
            // Нет смысла искать в пустоте на 2 метра дальше.
            // Добавляем небольшой буфер (50мм) на всякий случай.
            const searchLimitY = Math.min(this.gridH - mask.height, this.maxFilledY + mask.height + 50);

            // Сканируем лист для ЭТОЙ ротации
            let foundPosForRot: { x: number, y: number } | null = null;

            yLoop: for (let y = 0; y <= searchLimitY; y += step) {
                // UI responsiveness break
                if (y % 200 === 0) await new Promise(r => setTimeout(r, 0));

                for (let x = 0; x <= limitX; x += step) {
                    if (!this.checkCollision(x, y, mask)) {
                        foundPosForRot = { x, y };
                        break yLoop; // Нашли лучшее место для ЭТОЙ ротации (т.к. сканируем Y->X)
                    }
                }
            }

            if (foundPosForRot) {
                const candidate: PlacedResult = {
                    x: foundPosForRot.x * this.resolution,
                    y: foundPosForRot.y * this.resolution,
                    rotation: rot,
                    width: mask.width * this.resolution,
                    height: mask.height * this.resolution,
                    ox: mask.offsetX,
                    oy: mask.offsetY
                };

                // Сравниваем с текущим лучшим результатом
                // Приоритет: Чем меньше Y, тем лучше. При равном Y, чем меньше X.
                if (!bestResult) {
                    bestResult = candidate;
                } else {
                    if (candidate.y < bestResult.y) {
                        bestResult = candidate;
                    } else if (candidate.y === bestResult.y && candidate.x < bestResult.x) {
                        bestResult = candidate;
                    }
                }
            }
        }

        return bestResult;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return;

        const mask = this.getOrGenerateMask(partDef, result.rotation);

        const gridX = Math.round(result.x / this.resolution);
        const gridY = Math.round(result.y / this.resolution);

        this.writeMaskToGrid(gridX, gridY, mask);

        // Обновляем границу заполнения
        const itemBottomY = gridY + mask.height;
        if (itemBottomY > this.maxFilledY) {
            this.maxFilledY = itemBottomY;
        }

        this.placedItems.push({ item, result });
    }

    getPlacedItems() {
        return this.placedItems;
    }

    // --- Private Methods ---

    private checkCollision(sx: number, sy: number, mask: RasterMask): boolean {
        // Проверка границ массива (fail-safe)
        if (sx + mask.width > this.gridW || sy + mask.height > this.gridH) return true;

        // Быстрая проверка центра (эвристика: часто коллизия бывает в центре детали)
        const centerY = Math.floor(mask.height / 2);
        const centerX = Math.floor(mask.width / 2);
        const sheetIdxCenter = (sy + centerY) * this.gridW + (sx + centerX);
        const maskIdxCenter = centerY * mask.width + centerX;

        if (mask.data[maskIdxCenter] === 1 && this.grid[sheetIdxCenter] === 1) return true;

        // Полная проверка
        for (let my = 0; my < mask.height; my++) {
            // Оптимизация: вычисляем индексы строк заранее
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    if (this.grid[sheetRowOffset + mx] === 1) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private writeMaskToGrid(sx: number, sy: number, mask: RasterMask) {
        for (let my = 0; my < mask.height; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    this.grid[sheetRowOffset + mx] = 1;
                }
            }
        }
    }

    private getOrGenerateMask(part: Part, rotation: number): RasterMask {
        const key = `${part.id}_${rotation}`;
        if (this.maskCache.has(key)) {
            return this.maskCache.get(key)!;
        }

        const extents = getRotatedExtents(part, rotation, this.tools);

        // Учитываем spacing в маске
        const spacing = Math.ceil(Math.max(this.spacingX, this.spacingY) / this.resolution);

        const rawW = Math.ceil(extents.width / this.resolution);
        const rawH = Math.ceil(extents.height / this.resolution);

        // Маска чуть больше реальной детали на величину зазора
        const maskW = rawW + spacing; 
        const maskH = rawH + spacing;

        const data = new Uint8Array(maskW * maskH);

        const rad = -rotation * Math.PI / 180;
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);

        for (let y = 0; y < rawH; y++) {
            for (let x = 0; x < rawW; x++) {
                const bboxX = x * this.resolution;
                const bboxY = y * this.resolution;

                // FIX: Subtract offset to map Image Space (0..W) to Part Space (minX..maxX)
                // extents.ox = -minX. So bboxX - ox = bboxX + minX (if ox was +).
                // Wait. ox = -minX (positive value).
                // coordinate = bboxX + minX = bboxX - ox.
                const rotX = bboxX - extents.ox;
                const rotY = bboxY - extents.oy;

                const localX = rotX * cos - rotY * sin;
                const localY = rotX * sin + rotY * cos;

                if (isPointInsideContour({ x: localX, y: localY }, part.geometry)) {
                    // Заполняем саму точку
                    const idx = y * maskW + x;
                    data[idx] = 1;

                    // "Раздуваем" точку на spacing (вправо и вниз)
                    // Это создает зону безопасности вокруг детали
                    if (spacing > 0) {
                        // Рисуем линию вправо
                        for(let s=1; s<=spacing; s++) {
                            if (x + s < maskW) data[y * maskW + (x + s)] = 1;
                        }
                        // Рисуем линию вниз (и прямоугольник заполнения)
                        for(let sy=1; sy<=spacing; sy++) {
                            if (y + sy < maskH) {
                                const rowOff = (y + sy) * maskW;
                                for(let sx=0; sx<=spacing; sx++) {
                                    if (x + sx < maskW) data[rowOff + (x + sx)] = 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        const mask: RasterMask = {
            width: maskW,
            height: maskH,
            data: data,
            offsetX: extents.ox,
            offsetY: extents.oy
        };

        this.maskCache.set(key, mask);
        return mask;
    }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, isPointInsideContour } from '../../geometry';

interface RasterMask {
    width: number;
    height: number;
    data: Uint8Array; // 1 = Part Material, 0 = Empty
    offsetX: number;  // Смещение внутри маски до начала координат (0,0) детали
    offsetY: number;
}

export class ComplexPacker implements INestingPacker {
    // Глобальная сетка листа: 1D массив, эмулирующий 2D (index = y * width + x)
    // 0 = Свободно, 1 = Занято
    private grid: Uint8Array;
    private readonly gridW: number;
    private readonly gridH: number;
    private readonly resolution: number = 1; // 1 пиксель = 1 мм (Максимальная точность)

    // Кэш растеризованных масок для (PartId + Rotation)
    // Ключ: `${partId}_${rotation}`
    private maskCache: Map<string, RasterMask> = new Map();

    private placedItems: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.gridW = Math.ceil(sheetW / this.resolution);
        this.gridH = Math.ceil(sheetH / this.resolution);
        this.grid = new Uint8Array(this.gridW * this.gridH);
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        // Собираем уникальные ротации
        const rotations = Array.from(new Set([
            ...(item.preferredRotation !== undefined ? [item.preferredRotation] : []),
            ...item.allowedRotations
        ]));

        const step = 1; // Шаг 1мм по просьбе пользователя для максимальной плотности

        let bestResult: PlacedResult | null = null;

        // Стратегия: LEFT-MOST PACKING (Приоритет X)
        // Мы ищем позицию с минимальным X. При равных X берем минимальный Y.
        // Это позволяет детали "всплывать" или "опускаться" по Y, чтобы найти "карман" левее.

        for (const rot of rotations) {
            const mask = this.getOrGenerateMask(partDef, rot);

            // Пропуск, если деталь больше листа
            if (mask.width > this.gridW || mask.height > this.gridH) continue;

            const limitX = this.gridW - mask.width;
            const limitY = this.gridH - mask.height;

            let foundPosForRot: { x: number, y: number } | null = null;

            // Внешний цикл по X: Мы хотим заполнять лист слева направо.
            // Это радикально меняет поведение по сравнению с построчным (Y-first) заполнением.
            // Теперь алгоритм проверит Y=0, Y=50, Y=100 для X=0, прежде чем перейти к X=1.
            xLoop: for (let x = 0; x <= limitX; x += step) {

                // Оптимизация отсечения (Pruning):
                // Если мы уже нашли решение в другой ротации с X=100, 
                // а сейчас мы проверяем X=101, то нет смысла продолжать эту ротацию.
                // Мы ищем МИНИМАЛЬНЫЙ X глобально.
                if (bestResult && (x * this.resolution) > bestResult.x) {
                    break xLoop; 
                }

                // Внутренний цикл по Y: Ищем любое свободное место по вертикали для текущего X
                for (let y = 0; y <= limitY; y += step) {
                    if (!this.checkCollision(x, y, mask)) {
                        foundPosForRot = { x, y };
                        break xLoop; // Для этой ротации это наилучший X (т.к. цикл X возрастает)
                    }
                }

                // UI responsiveness (реже, т.к. X цикл длиннее, но break срабатывает часто)
                if (x % 50 === 0) await new Promise(r => setTimeout(r, 0));
            }

            if (foundPosForRot) {
                const candidate: PlacedResult = {
                    x: foundPosForRot.x * this.resolution,
                    y: foundPosForRot.y * this.resolution,
                    rotation: rot,
                    width: mask.width * this.resolution,
                    height: mask.height * this.resolution,
                    ox: mask.offsetX,
                    oy: mask.offsetY
                };

                // Сравниваем с лучшим результатом других ротаций
                if (!bestResult) {
                    bestResult = candidate;
                } else {
                    // Приоритет 1: Меньше X
                    if (candidate.x < bestResult.x) {
                        bestResult = candidate;
                    } 
                    // Приоритет 2: При равном X, меньше Y (для компактности снизу)
                    else if (candidate.x === bestResult.x && candidate.y < bestResult.y) {
                        bestResult = candidate;
                    }
                }
            }
        }

        return bestResult;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return;

        const mask = this.getOrGenerateMask(partDef, result.rotation);

        const gridX = Math.round(result.x / this.resolution);
        const gridY = Math.round(result.y / this.resolution);

        this.writeMaskToGrid(gridX, gridY, mask);
        this.placedItems.push({ item, result });
    }

    getPlacedItems() {
        return this.placedItems;
    }

    // --- Private Methods ---

    private checkCollision(sx: number, sy: number, mask: RasterMask): boolean {
        // Быстрая проверка границ массива
        if (sx + mask.width > this.gridW || sy + mask.height > this.gridH) return true;

        // Оптимизация: Проверяем центр и углы сначала, так как там чаще всего бывают коллизии
        // Центр
        const cy = Math.floor(mask.height/2);
        const cx = Math.floor(mask.width/2);
        if (mask.data[cy * mask.width + cx] && this.grid[(sy + cy) * this.gridW + (sx + cx)]) return true;

        // Углы (TL, TR, BL, BR) - если там есть материал
        const mw = mask.width;
        const mh = mask.height;
        // TL
        if (mask.data[0] && this.grid[sy * this.gridW + sx]) return true;

        // Полный проход
        for (let my = 0; my < mh; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mw;

            for (let mx = 0; mx < mw; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    if (this.grid[sheetRowOffset + mx] === 1) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private writeMaskToGrid(sx: number, sy: number, mask: RasterMask) {
        for (let my = 0; my < mask.height; my++) {
            const sheetRowOffset = (sy + my) * this.gridW + sx;
            const maskRowOffset = my * mask.width;

            for (let mx = 0; mx < mask.width; mx++) {
                if (mask.data[maskRowOffset + mx] === 1) {
                    this.grid[sheetRowOffset + mx] = 1;
                }
            }
        }
    }

    private getOrGenerateMask(part: Part, rotation: number): RasterMask {
        const key = `${part.id}_${rotation}`;
        if (this.maskCache.has(key)) {
            return this.maskCache.get(key)!;
        }

        const extents = getRotatedExtents(part, rotation, this.tools);

        // Spacing: увеличиваем маску детали, чтобы обеспечить зазор.
        // Маска = Деталь + Spacing справа и снизу (условно).
        const spacing = Math.ceil(Math.max(this.spacingX, this.spacingY) / this.resolution);

        const rawW = Math.ceil(extents.width / this.resolution);
        const rawH = Math.ceil(extents.height / this.resolution);

        const maskW = rawW + spacing; 
        const maskH = rawH + spacing;

        const data = new Uint8Array(maskW * maskH);

        const rad = -rotation * Math.PI / 180;
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);

        for (let y = 0; y < rawH; y++) {
            for (let x = 0; x < rawW; x++) {
                const bboxX = x * this.resolution;
                const bboxY = y * this.resolution;

                // Перевод в систему координат детали
                const rotX = bboxX - extents.ox;
                const rotY = bboxY - extents.oy;

                const localX = rotX * cos - rotY * sin;
                const localY = rotX * sin + rotY * cos;

                if (isPointInsideContour({ x: localX, y: localY }, part.geometry)) {
                    const idx = y * maskW + x;
                    data[idx] = 1;

                    // Dilate (расширение) на величину spacing
                    if (spacing > 0) {
                        // Рисуем "тень" безопасности вправо
                        for(let s=1; s<=spacing; s++) {
                            if (x + s < maskW) data[y * maskW + (x + s)] = 1;
                        }
                        // Рисуем "тень" безопасности вниз
                        for(let sy=1; sy<=spacing; sy++) {
                            if (y + sy < maskH) {
                                const rowOff = (y + sy) * maskW;
                                for(let sx=0; sx<=spacing; sx++) {
                                    if (x + sx < maskW) data[rowOff + (x + sx)] = 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        const mask: RasterMask = {
            width: maskW,
            height: maskH,
            data: data,
            offsetX: extents.ox,
            offsetY: extents.oy
        };

        this.maskCache.set(key, mask);
        return mask;
    }
}

