export type SortStrategy = 
    | 'area-descending'           
    | 'perimeter-descending'      
    | 'aspect-ratio'              
    | 'hybrid-score'              
    | 'genetic-optimized';        

const calculatePerimeter = (width: number, height: number): number => 2 * (width + height);

const calculateComplexity = (width: number, height: number): number => {
    return Math.max(width, height) / Math.min(width, height);
};

const calculateHybridScore = (item: PackerItem): number => {
    const areaScore = item.area;
    const complexityScore = calculateComplexity(item.width, item.height);
    const perimeterScore = calculatePerimeter(item.width, item.height);
    return areaScore * 0.7 + complexityScore * areaScore * 0.2 + perimeterScore * 0.1;
};

// Simplified Genetic Optimizer for sequence
class GeneticOptimizer {
    optimize(items: PackerItem[]): PackerItem[] {
        // Full GA implementation is heavy, using a simplified heuristic shuffle for now
        // In a real implementation, this would mutate sequence order to minimize simulated height
        return items.sort((a, b) => calculateHybridScore(b) - calculateHybridScore(a));
    }
}

export const preparePackerItemsImproved = (
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[],
    strategy: SortStrategy = 'hybrid-score'
): PackerItem[] => {
    const items: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const ext0 = getRotatedExtents(part, 0, tools);
        const allowed: number[] = [0];
        if (sp.nesting.allow0_180) allowed.push(180);
        if (sp.nesting.allow90_270) { allowed.push(90); allowed.push(270); }

        for (let i = 0; i < sp.quantity; i++) {
            items.push({
                uid: generateId(),
                partId: sp.partId,
                name: part.name,
                width: ext0.width,
                height: ext0.height,
                offsetX: ext0.ox,
                offsetY: ext0.oy,
                allowedRotations: allowed,
                hasCommonLine: sp.nesting.commonLine,
                area: ext0.width * ext0.height,
                aspectRatio: ext0.width / ext0.height
            });
        }
    }

    switch (strategy) {
        case 'area-descending':
            return items.sort((a, b) => b.area - a.area);
        case 'perimeter-descending':
            return items.sort((a, b) => calculatePerimeter(b.width, b.height) - calculatePerimeter(a.width, a.height));
        case 'aspect-ratio':
            return items.sort((a, b) => calculateComplexity(b.width, b.height) - calculateComplexity(a.width, a.height));
        case 'hybrid-score':
            return items.sort((a, b) => calculateHybridScore(b) - calculateHybridScore(a));
        case 'genetic-optimized':
            return new GeneticOptimizer().optimize(items);
        default:
            return items.sort((a, b) => b.area - a.area);
    }
};

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, doPartsIntersect } from '../../geometry';

export class ComplexPackerFast implements INestingPacker {
    private placed: { item: PackerItem; result: PlacedResult }[] = [];
    private spatialGrid: Map<string, { item: PackerItem; result: PlacedResult }[]>;
    private gridCellSize: number = 100;

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.spatialGrid = new Map();
    }

    private getGridKeys(x: number, y: number, w: number, h: number): string[] {
        const minGx = Math.floor(x / this.gridCellSize);
        const maxGx = Math.floor((x + w) / this.gridCellSize);
        const minGy = Math.floor(y / this.gridCellSize);
        const maxGy = Math.floor((y + h) / this.gridCellSize);
        const keys: string[] = [];
        for (let gx = minGx; gx <= maxGx; gx++) {
            for (let gy = minGy; gy <= maxGy; gy++) keys.push(`${gx},${gy}`);
        }
        return keys;
    }

    private addToGrid(item: PackerItem, result: PlacedResult) {
        const keys = this.getGridKeys(result.x, result.y, result.width, result.height);
        const entry = { item, result };
        keys.forEach(k => {
            if (!this.spatialGrid.has(k)) this.spatialGrid.set(k, []);
            this.spatialGrid.get(k)!.push(entry);
        });
    }

    private getNearbyParts(x: number, y: number, w: number, h: number) {
        const keys = this.getGridKeys(x, y, w, h);
        const set = new Set<{ item: PackerItem; result: PlacedResult }>();
        keys.forEach(k => {
            const list = this.spatialGrid.get(k);
            if(list) list.forEach(p => set.add(p));
        });
        return Array.from(set);
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        const coarseStep = 10;
        const rotations = Array.from(new Set([...(item.preferredRotation !== undefined ? [item.preferredRotation] : []), ...item.allowedRotations]));

        // Try Left-Bottom strategy with adaptive step
        for (const rot of rotations) {
            const extents = getRotatedExtents(partDef, rot, this.tools);
            if (extents.width > this.sheetW || extents.height > this.sheetH) continue;

            // Coarse pass
            for (let x = 0; x <= this.sheetW - extents.width; x += coarseStep) {
                // UI Yield
                if (x % 500 === 0) await new Promise(r => setTimeout(r, 0));

                for (let y = 0; y <= this.sheetH - extents.height; y += coarseStep) {
                    if (!this.checkCollision(x, y, extents, partDef, rot)) {
                        // Found coarse spot, try to optimize locally (push left/down)
                        let bx = x, by = y;
                        // Simple local refinement could go here, for now return coarse
                        return { 
                            x: bx, y: by, rotation: rot, 
                            ox: extents.ox, oy: extents.oy, width: extents.width, height: extents.height 
                        };
                    }
                }
            }
        }
        return null;
    }

    private checkCollision(x: number, y: number, ext: {width:number, height:number, ox:number, oy:number}, partDef: Part, rot: number): boolean {
        const nearby = this.getNearbyParts(x, y, ext.width, ext.height);
        const origin = { x: x + ext.ox, y: y + ext.oy };

        for (const placed of nearby) {
            const pPartDef = this.parts.find(p => p.id === placed.item.partId);
            if (!pPartDef) continue;
            const pOrigin = { x: placed.result.x + placed.result.ox, y: placed.result.y + placed.result.oy };

            if (doPartsIntersect(partDef, origin, rot, pPartDef, pOrigin, placed.result.rotation, Math.max(this.spacingX, this.spacingY))) {
                return true;
            }
        }
        return false;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        this.placed.push({ item, result });
        this.addToGrid(item, result);
    }

    getPlacedItems() { return this.placed; }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, doPartsIntersect } from '../../geometry';

export class BottomLeftPacker implements INestingPacker {
    private placed: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {}

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        const rotations = [...item.allowedRotations];
        let bestPos: PlacedResult | null = null;
        let minY = Infinity;
        let minX = Infinity;

        // Candidate points: (0,0) and corners of existing items
        const candidates: Point[] = [{x:0, y:0}];
        this.placed.forEach(p => {
            candidates.push({ x: p.result.x + p.result.width + this.spacingX, y: p.result.y });
            candidates.push({ x: p.result.x, y: p.result.y + p.result.height + this.spacingY });
        });

        // Sort candidates by Y then X to prioritize bottom-left
        candidates.sort((a,b) => (a.y - b.y) || (a.x - b.x));

        for (const rot of rotations) {
            const ext = getRotatedExtents(partDef, rot, this.tools);
            if (ext.width > this.sheetW || ext.height > this.sheetH) continue;

            for (const pt of candidates) {
                if (pt.x + ext.width > this.sheetW || pt.y + ext.height > this.sheetH) continue;

                // Early exit if we already found a better Y
                if (bestPos && pt.y > bestPos.y) break; 

                const origin = { x: pt.x + ext.ox, y: pt.y + ext.oy };
                let collision = false;

                for (const placed of this.placed) {
                    const pDef = this.parts.find(p => p.id === placed.item.partId);
                    if(!pDef) continue;
                    const pOrigin = { x: placed.result.x + placed.result.ox, y: placed.result.y + placed.result.oy };

                    if (doPartsIntersect(partDef, origin, rot, pDef, pOrigin, placed.result.rotation, Math.max(this.spacingX, this.spacingY))) {
                        collision = true;
                        break;
                    }
                }

                if (!collision) {
                    if (pt.y < minY || (pt.y === minY && pt.x < minX)) {
                        minY = pt.y;
                        minX = pt.x;
                        bestPos = {
                            x: pt.x, y: pt.y, rotation: rot,
                            ox: ext.ox, oy: ext.oy, width: ext.width, height: ext.height
                        };
                    }
                    // Since candidates are sorted, the first valid one for this rotation is the best for this rotation (mostly)
                    // But we check all rotations.
                    break; 
                }
            }
        }

        return bestPos;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        this.placed.push({ item, result });
    }

    getPlacedItems() { return this.placed; }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings } from '../types';
import { generateId } from '../utils/helpers';
import { INestingPacker, NestingProgressUpdate } from './nesting/types';
import { selectStockSheet } from './nesting/utils';
import { preparePackerItemsImproved } from './nesting/scoring-improved';
import { RectanglePacker } from './nesting/algo/RectanglePacker';
import { ComplexPacker } from './nesting/algo/ComplexPacker';
import { ComplexPackerFast } from './nesting/algo/ComplexPackerFast';
import { BottomLeftPacker } from './nesting/algo/BottomLeftPacker';

export async function* nestingGeneratorImproved(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestingProgressUpdate> {

    // 1. Prepare items with selected sorting strategy
    const itemsToPack = preparePackerItemsImproved(
        scheduledParts, 
        allParts, 
        tools, 
        settings.sortStrategy || 'hybrid-score'
    );

    const totalToPack = itemsToPack.length;
    let totalPackedCount = 0;
    const completedSheets: NestResultSheet[] = [];
    let remainingItems = [...itemsToPack];

    // 2. Loop until done
    while (remainingItems.length > 0) {
        const stockSheet = selectStockSheet(settings);
        if (!stockSheet) break;

        const effectiveW = stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight;
        const effectiveH = stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom;

        let packer: INestingPacker;
        const algo = settings.algorithm || 'hybrid';

        if (settings.nestAsRectangle || algo === 'rectangle-basic') {
            packer = new RectanglePacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, settings.useCommonLine, allParts, tools);
        } else if (algo === 'complex-fast') {
            packer = new ComplexPackerFast(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);
        } else if (algo === 'bottom-left') {
            packer = new BottomLeftPacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);
        } else if (algo === 'complex-basic') {
            packer = new ComplexPacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);
        } else {
            // Hybrid default
            if (remainingItems.length < 15) {
                packer = new BottomLeftPacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);
            } else {
                packer = new ComplexPackerFast(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);
            }
        }

        let packedOnThisSheet: string[] = [];

        for (const item of remainingItems) {
            const pos = await packer.findPosition(item);
            if (pos) {
                packer.placeItem(item, pos);
                packedOnThisSheet.push(item.uid);
                totalPackedCount++;
                yield { 
                    sheets: [...completedSheets], 
                    progress: (totalPackedCount / totalToPack) * 100, 
                    status: `Размещение: ${item.name} (${algo})` 
                };
            }
        }

        if (packedOnThisSheet.length === 0) {
            console.error("Item too big for sheet", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        remainingItems = remainingItems.filter(it => !packedOnThisSheet.includes(it.uid));

        const placedItems = packer.getPlacedItems();
        const usedAreaPx = placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = stockSheet.width * stockSheet.height;

        completedSheets.push({
            id: generateId(),
            sheetName: `Sheet ${completedSheets.length + 1}`,
            stockSheetId: stockSheet.id,
            width: stockSheet.width,
            height: stockSheet.height,
            material: stockSheet.material,
            thickness: stockSheet.thickness,
            usedArea: (usedAreaPx / totalAreaPx) * 100,
            scrapPercentage: 100 - (usedAreaPx / totalAreaPx) * 100,
            partCount: placedItems.length,
            quantity: 1,
            placedParts: placedItems.map(p => ({
                id: generateId(),
                partId: p.item.partId,
                x: p.result.x + settings.sheetMarginLeft + p.result.ox,
                y: p.result.y + settings.sheetMarginBottom + p.result.oy,
                rotation: p.result.rotation
            }))
        });

        yield { sheets: [...completedSheets], progress: (totalPackedCount / totalToPack) * 100, status: `Лист #${completedSheets.length} готов` };
    }
}

